llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "In normal subjects, d3-verapamil, a close verapamil-scaffold analogue, had a mean absolute oral bioavailability of 22.0%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In healthy subjects, verapamil absolute bioavailability after a 120 mg oral dose was 35% ± 7%, clearly exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Gallopamil, a close verapamil analogue with an additional methoxy group, showed 96.3% oral bioavailability in humans, indicating that modest structural changes in this scaffold can yield high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Vernakalant, a dimethoxyphenethylamine-derived drug, had an absolute oral bioavailability of 71 ± 21% in healthy volunteers, supporting that this chemotype can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Verapamil bioavailability averaged 19.4% in healthy young men, slightly below the 20% threshold, demonstrating that first-pass metabolism can reduce F in this scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a verapamil-like dimethoxyphenethylamine with a cyclic lactam-benzazepinone head. The closest analogues, verapamil and gallopamil, show human oral bioavailability around 20-35% and up to 96%, respectively; another dimethoxyphenethylamine-derived drug, vernakalant, shows 58-71% F. Although verapamil is borderline/low in some studies due to first-pass metabolism, the structural change to a lactam and the basic, moderately lipophilic scaffold favor absorption and F ≥ 20%. Less similar low-F analogues have distinct solubility, efflux, or metabolic liabilities not shared by the query.",
  "evidence_gaps": [
    "No direct human bioavailability measurement for zatebradine is present in the provided evidence.",
    "The closest verapamil data are borderline and variable, spanning roughly 10-35% F.",
    "The effect of replacing the nitrile/isopropyl head with a cyclic lactam on first-pass metabolism is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

